3class Board {
4
5    // count variable
6    int count = 0;
7    String board[] = { " ", " ", " ", " ", " ", " ", " ", " ", " " };
8
9    void printBoard() {
10
11        System.out.println(" " + board[0] + " | " + board[1] + " | " + board[2]);
12        System.out.println("-----------");
13        System.out.println(" " + board[3] + " | " + board[4] + " | " + board[5]);
14        System.out.println("-----------");
15        System.out.println(" " + board[6] + " | " + board[7] + " | " + board[8]);
16
17    }
18
19    boolean updateBoard(int position, String type) {
20
21        // if a player selects position n, n-1 index should be updated
22        // if the position is not already filled, update the board
23        if (board[position - 1] == " ") {
24            board[position - 1] = type;
25
26            // increase the value of count by 1
27            count++;
28            return true;
29        }
30
31        // if the position is already filled, ask user to select another position
32        else {
33            System.out.println("Position already selected. Select another position.");
34            return false;
35
36        }
37    }
38
39    // If all fields are selected and there is no winner, it's draw
40    // Returning true if it's draw
41    boolean checkDraw() {
42
43        // check if count == 9
44        if (count == 9) {
45            return true;
46        } 
47        else {
48            return false;
49        }
50    }
51
52    // if three symbols appears in a row, returning True
53    boolean checkWinner(String type) {
54        if ((board[0] == type && board[1] == type && board[2] == type)
55                || (board[3] == type && board[4] == type && board[5] == type)
56                || (board[6] == type && board[7] == type && board[8] == type)
57                || (board[0] == type && board[3] == type && board[6] == type)
58                || (board[1] == type && board[4] == type && board[7] == type)
59                || (board[2] == type && board[5] == type && board[8] == type)
60                || (board[0] == type && board[4] == type && board[8] == type)
61                || (board[2] == type && board[4] == type && board[6] == type)) {
62            return true;
63        }
64
65        else {
66            return false;
67        }
68
69    }
70}
