93class Game {
94
95    Board board = new Board();
96    Player player1 = new Player("X");
97    Player player2 = new Player("O");
98
99    Player currentPlayer = player1;
100
101    void play() {
102        // using an infinite loop to run the game
103        // we will later add conditions to terminate the loop
104        String message = "enter the position (1 - 9):";
105        while (true) {
106
107            System.out.println(currentPlayer.name + " " + message);
108            Scanner input = new Scanner(System.in);
109            int position = input.nextInt();
110
111            // the updateBoard() method return true if
112            // the user selected position is not already filled
113            if (board.updateBoard(position, currentPlayer.type)) {
114
115                board.printBoard();
116
117                // checking winner each time after updating the board
118                if (board.checkWinner(currentPlayer.type)) {
119                    System.out.println(currentPlayer.name + " wins!");
120                    break;
121                }
122
123                // checking draw each time after updating the board
124                else if (board.checkDraw()) {
125                    System.out.println("Game is a draw!");
126                    break;
127                }
128
129                // changing current player when board is updated
130                else {
131                    if (currentPlayer == player1) {
132                        currentPlayer = player2;
133                    }
134
135                    else {
136                        currentPlayer = player1;
137                    }
138
139                }
140            }
141
142        }
143
144    }
145
146}
